          "pattern": "\\b(?:with|alongside|next to|together with)\\s+(?:\\d+|one|two|three|four|five|six|seven|eight|nine|ten|a\\s+couple(?:\\s+of)?|a\\s+few|several)\\s+(?:coworkers?|colleagues?|teammates?|classmates?|students?|friends?|neighbors?|clients?|customers?|participants?|attendees?|family(?:\\s+members)?|siblings?|brothers?|sisters?|parents?|kids?|children|patients?)\\b",
